@pytest.mark.parametrize("node_id", NODE_IDS)
def test_node_port_xi_responds_200(client, node_id):
    response = client.post(f"/{node_id}/port-xi", json=NODE_PAYLOADS[node_id])
    assert response.status_code == 200, (
        f"{node_id}/port-xi returned {response.status_code}: {response.text}"
    )
    body = response.json()
    assert body.get("node") == node_id or "ok" in body, (
        f"{node_id} returned unexpected body shape: {body}"
    )


